UPDATE lessons SET title='Mental Subtraction: Bridge and Compensate',data=json_patch(data,'{"seed_key":"s2-mat-y3-w06-l2","title":"Mental Subtraction: Bridge and Compensate","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":6,"lesson_number":2,"duration_minutes":60,"child_mission":"Learn mental subtraction: bridge and compensate with guided explanations, checks and a new independent problem.","learning_intention":"We are learning to use mental subtraction: bridge and compensate and explain the reasoning.","success_criteria":["I can describe the new skill.","I can follow a worked example and explain why it works.","I can practise and check my answers.","I can solve an independent challenge.","I can check the result and correct one mistake."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept reminders","cards":[{"front":"Subtract tens and ones","back":"83−27=83−20−7=56"},{"front":"Cross a friendly ten","back":"62−18=62−2−16=44"},{"front":"Count upwards for a difference","back":"91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13"},{"front":"Check by addition","back":"74−29=74−30+1=45; 45+29=74"}]}],"printable_resource":{"title":"Mental Subtraction: Bridge and Compensate","instructions":"Try the teaching and the independent task, then check your steps.","passage":"A Year 3 class is checking the answers to several subtraction problems using different methods.","prompts":["Record the key information.","Show the method.","Check the result."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Subtract tens and ones","explain":"**Why this works:** 83−27=83−20−7=56\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates mental subtraction: bridge and compensate.","example":"**MY THINKING:** 83−27=83−20−7=56\n\n**YOUR TRY:** A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"83−27=83−20−7=56 Keep your work accurate and name the strategy.","check":{"question":"83−27?","options":["46","56","66","57"],"correct_index":1,"explanation":"The correct choice is 56. 83−27=83−20−7=56"},"visual_before":[{"episode":{"title":"Investigate Mental Subtraction: Bridge and Compensate","transcript":"Pip: I found a tricky task and need a reliable method.\nJuno: Look carefully at the example and explain each step.\nPip: I can use the worked example to check my answer.\nJuno: Pause and try solving one part before the next stage.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I found a tricky task and need a reliable method. How do I decide what to do?"},{"who":"juno","text":"This is mental subtraction: bridge and compensate. Look carefully at the example and explain each step."},{"who":"pip","text":"I can use the worked example to check my answer and explain my method."},{"who":"juno","text":"Pause and try solving one part before the next stage. Check it carefully, including the original numbers or supporting words.","pause_after":true}]}]}}]},{"icon":"📚","title":"Cross a friendly ten","explain":"**Why this works:** 62−18=62−2−16=44\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates mental subtraction: bridge and compensate.","example":"**MY THINKING:** 62−18=62−2−16=44\n\n**YOUR TRY:** A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"62−18=62−2−16=44 Keep your work accurate and name the strategy.","check":{"question":"62−18?","options":["44","54","46","42"],"correct_index":0,"explanation":"The correct choice is 44. 62−18=62−2−16=44"}},{"icon":"✏️","title":"Count upwards for a difference","explain":"**Why this works:** 91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates mental subtraction: bridge and compensate.","example":"**MY THINKING:** 91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13\n\n**YOUR TRY:** A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13 Keep your work accurate and name the strategy.","check":{"question":"91−78?","options":["12","13","14","23"],"correct_index":1,"explanation":"The correct choice is 13. 91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13"}},{"icon":"✅","title":"Check by addition","explain":"**Why this works:** 74−29=74−30+1=45; 45+29=74\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates mental subtraction: bridge and compensate.","example":"**MY THINKING:** 74−29=74−30+1=45; 45+29=74\n\n**YOUR TRY:** A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"74−29=74−30+1=45; 45+29=74 Keep your work accurate and name the strategy.","check":{"question":"74−29?","options":["35","44","45","55"],"correct_index":2,"explanation":"The correct choice is 45. 74−29=74−30+1=45; 45+29=74"}}],"worked_example":"A Year 3 class is checking the answers to several subtraction problems using different methods.\n\n1. Subtract tens and ones: 83−27=83−20−7=56\n\n2. Cross a friendly ten: 62−18=62−2−16=44\n\n3. Count upwards for a difference: 91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13\n\n4. Check by addition: 74−29=74−30+1=45; 45+29=74\n\nCheck how the final answer follows from the original information.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 180\"><rect width=\"590\" height=\"180\" rx=\"10\" fill=\"#f6f9f7\"/><text x=\"12\" y=\"28\" font-family=\"Arial\" font-size=\"18\">Learn, practise and check</text><rect x=\"8\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e0eee4\"/><text x=\"16\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP ONE</text><rect x=\"151\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e8eefa\"/><text x=\"159\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP TWO</text><rect x=\"294\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e0eee4\"/><text x=\"302\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP THREE</text><rect x=\"437\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e8eefa\"/><text x=\"445\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP FOUR</text></svg>","alt":"Four-stage reminder for Mental Subtraction: Bridge and Compensate.","caption":"Use this to keep track of the four teaching ideas."}],"guided_practice":"**First follow the model:** 83−27=83−20−7=56 62−18=62−2−16=44 91−78: 78→80 (+2), 80→90 (+10), 90→91 (+1), answer 13 74−29=74−30+1=45; 45+29=74\n\n**Now attempt a new challenge before checking the answer:** A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.\n\n**Feedback:** 81 seedlings remain. 146−38=108, then 108−27=81. Alternatively 38+27=65 and 146−65=81.\n\n**Important correction:** 146−38 is 108, not 118. Subtract 40 and then add 2 back. Check: 81+38+27=146.","independent_task":"A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.","response_prompt":"A garden club has 146 seedlings. It gives away 38, then another 27. Find how many remain using two mental methods and check your answer.","quiz":[{"type":"multiple_choice","question":"83−27?","options":["46","56","66","57"],"correct_index":1,"explanation":"56 is supported by the original worked examples."},{"type":"multiple_choice","question":"62−18?","options":["44","54","46","42"],"correct_index":0,"explanation":"44 is supported by the original worked examples."},{"type":"multiple_choice","question":"91−78?","options":["12","13","14","23"],"correct_index":1,"explanation":"13 is supported by the original worked examples."},{"type":"multiple_choice","question":"74−29?","options":["35","44","45","55"],"correct_index":2,"explanation":"45 is supported by the original worked examples."},{"type":"multiple_choice","question":"85−36?","options":["39","49","59","50"],"correct_index":1,"explanation":"49 is supported by the original worked examples."},{"type":"multiple_choice","question":"70−28?","options":["38","40","42","48"],"correct_index":2,"explanation":"42 is supported by the original worked examples."},{"type":"multiple_choice","question":"102−97?","options":["3","4","5","6"],"correct_index":2,"explanation":"5 is supported by the original worked examples."},{"type":"multiple_choice","question":"146−38−27?","options":["71","81","91","101"],"correct_index":1,"explanation":"81 is supported by the original worked examples."},{"type":"short_answer","question":"Complete the challenge, showing the supporting information or calculations.","sample_answer":"81 seedlings remain. 146−38=108, then 108−27=81. Alternatively 38+27=65 and 146−65=81.","marking_guide":"Check all requested components against the supplied worked method.","explanation":"An answer needs accurate steps, not only a final number."},{"type":"short_answer","question":"Describe and correct a specific possible misconception.","sample_answer":"146−38 is 108, not 118. Subtract 40 and then add 2 back. Check: 81+38+27=146.","marking_guide":"Require a relevant check and accurate correction.","explanation":"An explanation shows understanding."}],"parent_notes":"Parent: Check the child''s independent strategy or text evidence and ask them to explain one detail without copying.\n\nParent: Written model one: 81 seedlings remain. 146−38=108, then 108−27=81. Alternatively 38+27=65 and 146−65=81.\n\nParent: Written model two: 146−38 is 108, not 118. Subtract 40 and then add 2 back. Check: 81+38+27=146.\n\nParent: Save original evidence, manually check written work and verify syllabus alignment separately.","evidence_instructions":"Keep the guided practice, original task, one corrected error and the two written quiz responses.","offline_alternative":"Use paper and a pencil for the teaching and independent problem. A parent may record oral explanations.","extension":"Create an additional mental subtraction: bridge and compensate problem and justify its solution.","stage_hints":{"accept":["Read the instruction and find the relevant information for Mental Subtraction: Bridge and Compensate.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach0":["Read the instruction and find the relevant information for Subtract tens and ones.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach1":["Read the instruction and find the relevant information for Cross a friendly ten.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."]