UPDATE lessons SET title='Written Subtraction: Regroup Across Zero',data=json_patch(data,'{"seed_key":"s2-mat-y3-w06-l3","title":"Written Subtraction: Regroup Across Zero","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":6,"lesson_number":3,"duration_minutes":60,"child_mission":"Learn written subtraction: regroup across zero with guided explanations, checks and a new independent problem.","learning_intention":"We are learning to use written subtraction: regroup across zero and explain the reasoning.","success_criteria":["I can describe the new skill.","I can follow a worked example and explain why it works.","I can practise and check my answers.","I can solve an independent challenge.","I can check the result and correct one mistake."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept reminders","cards":[{"front":"Line up place values","back":"402−178 has 4 hundreds, 0 tens, 2 ones."},{"front":"Exchange a hundred into tens","back":"Exchange 1 hundred to make 3 hundreds and 10 tens."},{"front":"Exchange a ten into ones","back":"Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones."},{"front":"Subtract and inverse-check","back":"12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402."}]}],"printable_resource":{"title":"Written Subtraction: Regroup Across Zero","instructions":"Try the teaching and the independent task, then check your steps.","passage":"A Year 3 class is checking the answers to several subtraction problems using different methods.","prompts":["Record the key information.","Show the method.","Check the result."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Line up place values","explain":"**Why this works:** 402−178 has 4 hundreds, 0 tens, 2 ones.\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates written subtraction: regroup across zero.","example":"**MY THINKING:** 402−178 has 4 hundreds, 0 tens, 2 ones.\n\n**YOUR TRY:** A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"402−178 has 4 hundreds, 0 tens, 2 ones. Keep your work accurate and name the strategy.","check":{"question":"402−178?","options":["214","224","234","324"],"correct_index":1,"explanation":"The correct choice is 224. 402−178 has 4 hundreds, 0 tens, 2 ones."},"visual_before":[{"episode":{"title":"Investigate Written Subtraction: Regroup Across Zero","transcript":"Pip: I found a tricky task and need a reliable method.\nJuno: Look carefully at the example and explain each step.\nPip: I can use the worked example to check my answer.\nJuno: Pause and try solving one part before the next stage.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I found a tricky task and need a reliable method. How do I decide what to do?"},{"who":"juno","text":"This is written subtraction: regroup across zero. Look carefully at the example and explain each step."},{"who":"pip","text":"I can use the worked example to check my answer and explain my method."},{"who":"juno","text":"Pause and try solving one part before the next stage. Check it carefully, including the original numbers or supporting words.","pause_after":true}]}]}}]},{"icon":"📚","title":"Exchange a hundred into tens","explain":"**Why this works:** Exchange 1 hundred to make 3 hundreds and 10 tens.\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates written subtraction: regroup across zero.","example":"**MY THINKING:** Exchange 1 hundred to make 3 hundreds and 10 tens.\n\n**YOUR TRY:** A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"Exchange 1 hundred to make 3 hundreds and 10 tens. Keep your work accurate and name the strategy.","check":{"question":"Ones after exchanging in 402?","options":["2","10","12","20"],"correct_index":2,"explanation":"The correct choice is 12. Exchange 1 hundred to make 3 hundreds and 10 tens."}},{"icon":"✏️","title":"Exchange a ten into ones","explain":"**Why this works:** Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones.\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates written subtraction: regroup across zero.","example":"**MY THINKING:** Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones.\n\n**YOUR TRY:** A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones. Keep your work accurate and name the strategy.","check":{"question":"Tens remaining after exchanging 402?","options":["0","8","9","10"],"correct_index":2,"explanation":"The correct choice is 9. Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones."}},{"icon":"✅","title":"Subtract and inverse-check","explain":"**Why this works:** 12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402.\n\n**Remember:** Use the original facts, numbers and positions rather than guessing. This lesson investigates written subtraction: regroup across zero.","example":"**MY THINKING:** 12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402.\n\n**YOUR TRY:** A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.\n\n**CHECK:** Read the model and explain where each number or supporting detail came from.","notice":"12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402. Keep your work accurate and name the strategy.","check":{"question":"351−176?","options":["165","175","185","275"],"correct_index":1,"explanation":"The correct choice is 175. 12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402."}}],"worked_example":"A Year 3 class is checking the answers to several subtraction problems using different methods.\n\n1. Line up place values: 402−178 has 4 hundreds, 0 tens, 2 ones.\n\n2. Exchange a hundred into tens: Exchange 1 hundred to make 3 hundreds and 10 tens.\n\n3. Exchange a ten into ones: Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones.\n\n4. Subtract and inverse-check: 12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402.\n\nCheck how the final answer follows from the original information.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 180\"><rect width=\"590\" height=\"180\" rx=\"10\" fill=\"#f6f9f7\"/><text x=\"12\" y=\"28\" font-family=\"Arial\" font-size=\"18\">Learn, practise and check</text><rect x=\"8\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e0eee4\"/><text x=\"16\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP ONE</text><rect x=\"151\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e8eefa\"/><text x=\"159\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP TWO</text><rect x=\"294\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e0eee4\"/><text x=\"302\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP THREE</text><rect x=\"437\" y=\"60\" width=\"135\" height=\"95\" rx=\"8\" fill=\"#e8eefa\"/><text x=\"445\" y=\"100\" font-family=\"Arial\" font-size=\"13\">STEP FOUR</text></svg>","alt":"Four-stage reminder for Written Subtraction: Regroup Across Zero.","caption":"Use this to keep track of the four teaching ideas."}],"guided_practice":"**First follow the model:** 402−178 has 4 hundreds, 0 tens, 2 ones. Exchange 1 hundred to make 3 hundreds and 10 tens. Exchange 1 ten: now 3 hundreds, 9 tens and 12 ones. 12−8=4, 9−7=2, 3−1=2; answer 224. Check 224+178=402.\n\n**Now attempt a new challenge before checking the answer:** A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.\n\n**Feedback:** 703−286=417; 703 becomes 6 hundreds, 9 tens, 13 ones; 13−6=7, 9−8=1, 6−2=4. Also 514−267=247.\n\n**Important correction:** The zero tens in 703 needs a hundred exchanged into ten tens before exchanging a ten into ones. Verify 417+286=703 and 247+267=514.","independent_task":"A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.","response_prompt":"A collection has 703 cans and 286 are taken away. Show both exchanges, subtract 703−286, then solve 514−267 and check both by addition.","quiz":[{"type":"multiple_choice","question":"402−178?","options":["214","224","234","324"],"correct_index":1,"explanation":"224 is supported by the original worked examples."},{"type":"multiple_choice","question":"Ones after exchanging in 402?","options":["2","10","12","20"],"correct_index":2,"explanation":"12 is supported by the original worked examples."},{"type":"multiple_choice","question":"Tens remaining after exchanging 402?","options":["0","8","9","10"],"correct_index":2,"explanation":"9 is supported by the original worked examples."},{"type":"multiple_choice","question":"351−176?","options":["165","175","185","275"],"correct_index":1,"explanation":"175 is supported by the original worked examples."},{"type":"multiple_choice","question":"600−245?","options":["345","355","365","455"],"correct_index":1,"explanation":"355 is supported by the original worked examples."},{"type":"multiple_choice","question":"703−286?","options":["407","417","427","517"],"correct_index":1,"explanation":"417 is supported by the original worked examples."},{"type":"multiple_choice","question":"514−267?","options":["237","247","257","347"],"correct_index":1,"explanation":"247 is supported by the original worked examples."},{"type":"multiple_choice","question":"Check for 703−286?","options":["417+286=703","417−286=703","703+286=417","286−417=703"],"correct_index":0,"explanation":"417+286=703 is supported by the original worked examples."},{"type":"short_answer","question":"Complete the challenge, showing the supporting information or calculations.","sample_answer":"703−286=417; 703 becomes 6 hundreds, 9 tens, 13 ones; 13−6=7, 9−8=1, 6−2=4. Also 514−267=247.","marking_guide":"Check all requested components against the supplied worked method.","explanation":"An answer needs accurate steps, not only a final number."},{"type":"short_answer","question":"Describe and correct a specific possible misconception.","sample_answer":"The zero tens in 703 needs a hundred exchanged into ten tens before exchanging a ten into ones. Verify 417+286=703 and 247+267=514.","marking_guide":"Require a relevant check and accurate correction.","explanation":"An explanation shows understanding."}],"parent_notes":"Parent: Check the child''s independent strategy or text evidence and ask them to explain one detail without copying.\n\nParent: Written model one: 703−286=417; 703 becomes 6 hundreds, 9 tens, 13 ones; 13−6=7, 9−8=1, 6−2=4. Also 514−267=247.\n\nParent: Written model two: The zero tens in 703 needs a hundred exchanged into ten tens before exchanging a ten into ones. Verify 417+286=703 and 247+267=514.\n\nParent: Save original evidence, manually check written work and verify syllabus alignment separately.","evidence_instructions":"Keep the guided practice, original task, one corrected error and the two written quiz responses.","offline_alternative":"Use paper and a pencil for the teaching and independent problem. A parent may record oral explanations.","extension":"Create an additional written subtraction: regroup across zero problem and justify its solution.","stage_hints":{"accept":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach0":["Read the instruction and find the relevant information for Line up place values.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach1":["Read the instruction and find the relevant information for Exchange a hundred into tens.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach2":["Read the instruction and find the relevant information for Exchange a ten into ones.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"teach3":["Read the instruction and find the relevant information for Subtract and inverse-check.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"learn":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"guided":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"write":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"quiz":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."],"submit":["Read the instruction and find the relevant information for Written Subtraction: Regroup Across Zero.","Think about how the worked example makes each step clear.","Check a specific number or clue, then explain your own answer."]}}') WHERE seed_key='s2-mat-y3-w06-l3';

